#include "exotic/cognition/storage_schema.hpp"
#include <sqlite3.h>
#include <stdexcept>
#include <string>
namespace exotic::cognition { namespace {
void exec(sqlite3*db,const char*sql){char*e=nullptr;if(sqlite3_exec(db,sql,nullptr,nullptr,&e)!=SQLITE_OK){std::string m=e?e:sqlite3_errmsg(db);sqlite3_free(e);throw std::runtime_error(m);}}
void record(sqlite3*db,int v,const char*name){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db,"INSERT INTO schema_migrations(version,name,applied_at) VALUES(?,?,datetime('now'));",-1,&s,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));sqlite3_bind_int(s,1,v);sqlite3_bind_text(s,2,name,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_DONE){sqlite3_finalize(s);throw std::runtime_error(sqlite3_errmsg(db));}sqlite3_finalize(s);} }
int storage_schema_version(sqlite3*db){exec(db,"CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,name TEXT NOT NULL,applied_at TEXT NOT NULL);");sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db,"SELECT COALESCE(MAX(version),0) FROM schema_migrations;",-1,&s,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));int v=sqlite3_step(s)==SQLITE_ROW?sqlite3_column_int(s,0):0;sqlite3_finalize(s);return v;}
void apply_storage_migrations(sqlite3*db){int v=storage_schema_version(db);if(v<1){exec(db,"BEGIN IMMEDIATE;");try{exec(db,R"SQL(CREATE TABLE IF NOT EXISTS identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),id TEXT NOT NULL,name TEXT NOT NULL,self_description TEXT NOT NULL,avatar_kind TEXT NOT NULL,avatar_value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS beliefs(id TEXT PRIMARY KEY,proposition TEXT NOT NULL,confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS goals(id TEXT PRIMARY KEY,title TEXT NOT NULL,priority REAL NOT NULL CHECK(priority BETWEEN 0 AND 1),source TEXT NOT NULL,status TEXT NOT NULL);CREATE TABLE IF NOT EXISTS preferences(key TEXT PRIMARY KEY,weight REAL NOT NULL CHECK(weight BETWEEN -1 AND 1));CREATE TABLE IF NOT EXISTS drives(key TEXT PRIMARY KEY,level REAL NOT NULL,target REAL NOT NULL,learning_rate REAL NOT NULL);CREATE TABLE IF NOT EXISTS rewards(id TEXT PRIMARY KEY,source TEXT NOT NULL,value REAL NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS operator_sessions(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL,token_hash TEXT NOT NULL,expires_unix INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS thoughts(id TEXT PRIMARY KEY,subject TEXT NOT NULL,score REAL NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS episodes(id TEXT PRIMARY KEY,summary TEXT NOT NULL,salience REAL NOT NULL,reward REAL NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS semantic_memory(id TEXT PRIMARY KEY,topic TEXT NOT NULL,statement TEXT NOT NULL,confidence REAL NOT NULL,source_episode TEXT NOT NULL);CREATE TABLE IF NOT EXISTS personality_traits(key TEXT PRIMARY KEY,value REAL NOT NULL CHECK(value BETWEEN 0 AND 1),plasticity REAL NOT NULL CHECK(plasticity BETWEEN 0 AND 0.25));CREATE TABLE IF NOT EXISTS reflections(id TEXT PRIMARY KEY,observation TEXT NOT NULL,lesson TEXT NOT NULL,confidence REAL NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_goals_status_priority ON goals(status,priority DESC);CREATE INDEX IF NOT EXISTS idx_beliefs_confidence ON beliefs(confidence DESC);CREATE INDEX IF NOT EXISTS idx_rewards_created ON rewards(created_at DESC);)SQL");record(db,1,"core-agent-store");exec(db,"COMMIT;");}catch(...){exec(db,"ROLLBACK;");throw;}v=1;}if(v<2){exec(db,"BEGIN IMMEDIATE;");try{exec(db,R"SQL(CREATE TABLE IF NOT EXISTS choice_history(id TEXT PRIMARY KEY,subject TEXT NOT NULL,option_id TEXT NOT NULL,outcome TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,supersedes TEXT NOT NULL DEFAULT '');CREATE TABLE IF NOT EXISTS intentions(id TEXT PRIMARY KEY,subject TEXT NOT NULL,source_choice_id TEXT NOT NULL,state TEXT NOT NULL,strength REAL NOT NULL CHECK(strength BETWEEN 0 AND 1),reason TEXT NOT NULL);CREATE TABLE IF NOT EXISTS adaptation_history(id TEXT PRIMARY KEY,target TEXT NOT NULL,target_id TEXT NOT NULL,before_value REAL NOT NULL,after_value REAL NOT NULL,rationale TEXT NOT NULL,created_at TEXT NOT NULL,rolled_back INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS belief_evidence(id TEXT PRIMARY KEY,belief_id TEXT NOT NULL,source TEXT NOT NULL,statement TEXT NOT NULL,direction REAL NOT NULL,reliability REAL NOT NULL,observed_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS belief_revision_history(id INTEGER PRIMARY KEY AUTOINCREMENT,belief_id TEXT NOT NULL,before_proposition TEXT NOT NULL,after_proposition TEXT NOT NULL,before_confidence REAL NOT NULL,after_confidence REAL NOT NULL,rationale TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS attention_state(topic_id TEXT PRIMARY KEY,last_considered INTEGER NOT NULL DEFAULT 0,cooldown_until INTEGER NOT NULL DEFAULT 0,repeats_in_window INTEGER NOT NULL DEFAULT 0,stopped INTEGER NOT NULL DEFAULT 0);CREATE INDEX IF NOT EXISTS idx_intentions_state ON intentions(state);CREATE INDEX IF NOT EXISTS idx_belief_evidence_belief ON belief_evidence(belief_id);CREATE INDEX IF NOT EXISTS idx_revision_belief ON belief_revision_history(belief_id,id);)SQL");record(db,2,"cognition-state");exec(db,"COMMIT;");}catch(...){exec(db,"ROLLBACK;");throw;}v=2;}if(v<3){exec(db,"BEGIN IMMEDIATE;");try{exec(db,R"SQL(CREATE TABLE IF NOT EXISTS intention_transitions(id TEXT PRIMARY KEY,intention_id TEXT NOT NULL,from_state TEXT NOT NULL,to_state TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_intention_transitions_intention ON intention_transitions(intention_id,created_at);)SQL");record(db,3,"intention-transition-history");exec(db,"COMMIT;");}catch(...){exec(db,"ROLLBACK;");throw;}v=3;}if(v<4){exec(db,"BEGIN IMMEDIATE;");try{exec(db,R"SQL(ALTER TABLE intentions ADD COLUMN created_at TEXT NOT NULL DEFAULT '';ALTER TABLE intentions ADD COLUMN updated_at TEXT NOT NULL DEFAULT '';CREATE INDEX IF NOT EXISTS idx_intentions_state_updated ON intentions(state,updated_at);)SQL");record(db,4,"intention-lifecycle-metadata");exec(db,"COMMIT;");}catch(...){exec(db,"ROLLBACK;");throw;}v=4;}if(v<5){exec(db,"BEGIN IMMEDIATE;");try{exec(db,R"SQL(CREATE TABLE IF NOT EXISTS agency_cycles(id TEXT PRIMARY KEY,subject TEXT NOT NULL,volition_outcome TEXT NOT NULL,metacognition_engaged INTEGER NOT NULL,arbitration_count INTEGER NOT NULL,timing_count INTEGER NOT NULL,reconsideration_count INTEGER NOT NULL,external_action_requested INTEGER NOT NULL,external_action_authorized INTEGER NOT NULL,rationale TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_agency_cycles_created ON agency_cycles(created_at);)SQL");record(db,5,"agency-cycle-audit");exec(db,"COMMIT;");}catch(...){exec(db,"ROLLBACK;");throw;}}
}
} // namespace exotic::cognition
